package com.portfolio.agent.answer.intelligence.retrieval;
import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.*;
class RetrievalFallbackPolicyTest { @Test void vectorFailureGetsOneKeywordFallback(){EffectiveRetrievalPlan p=new EffectiveRetrievalPlan(RetrievalIntent.RECOMMENDATION_DISCOVERY,CorpusBackend.POSTGRESQL,SearchStrategy.HYBRID,null,null,"v1");EffectiveRetrievalPlan fallback=new RetrievalFallbackPolicy().fallbackFor(p,RetrievalAttemptFailure.VECTOR_UNAVAILABLE).orElseThrow();assertThat(fallback.getPrimaryStrategy()).isEqualTo(SearchStrategy.KEYWORD);assertThat(fallback.getFallbackStrategy()).isEmpty();} @Test void businessEmptyDoesNotBecomeInfrastructureFallback(){EffectiveRetrievalPlan p=new EffectiveRetrievalPlan(RetrievalIntent.EXACT_SUBJECT,CorpusBackend.POSTGRESQL,SearchStrategy.EXACT,SearchStrategy.KEYWORD,CorpusBackend.BUNDLE,"v1");assertThat(new RetrievalFallbackPolicy().fallbackFor(p,RetrievalAttemptFailure.BUSINESS_EMPTY)).isEmpty();} }
